<script setup lang="ts">
import {Head,router,useForm,usePage} from '@inertiajs/vue3';
import {computed} from 'vue';
const p=defineProps<{tokens:any[];users:any[];abilities:string[]}>();const page=usePage<any>();
const f=useForm<any>({user_id:'',name:'',abilities:[],expires_at:''});const created=computed(()=>page.props.flash?.api_token);
function create(){f.post('/api-tokens',{preserveScroll:true,onSuccess:()=>f.reset()});}function revoke(id:number){const reason=window.prompt('Arsyeja e revokimit (minimum 5 shenja):');if(reason&&reason.length>=5)router.post(`/api-tokens/${id}/revoke`,{reason},{preserveScroll:true});}
</script>
<template><Head title="API Tokens"/><div class="tp-page-heading"><div><div class="tp-eyebrow">QASJE PROGRAMATIKE E KUFIZUAR</div><h1>API tokens</h1><p>Tokeni shfaqet vetëm një herë. Përdorni kufirin më të ngushtë të lejeve dhe datë skadimi.</p></div></div><section v-if="created" class="tp-panel"><h2>Ruajeni tokenin tani</h2><code class="tp-notice block break-all">{{created}}</code></section><section class="tp-panel"><h2>Krijo token</h2><form @submit.prevent="create"><div class="tp-fields"><label class="tp-field"><span>Përdoruesi</span><select v-model="f.user_id" required><option value="">Zgjidhni…</option><option v-for="user in users" :key="user.id" :value="user.id">{{user.name}} · {{user.email}}</option></select></label><label class="tp-field"><span>Emri</span><input v-model="f.name" required/></label><label class="tp-field"><span>Skadon më</span><input v-model="f.expires_at" type="date"/></label><fieldset class="tp-repeat wide"><legend>Lejet e API</legend><label v-for="ability in abilities" :key="ability" class="block mb-2"><input v-model="f.abilities" type="checkbox" :value="ability"/> {{ability}}</label></fieldset></div><p v-for="(error,key) in f.errors" :key="key" class="tp-error">{{error}}</p><button class="tp-button" :disabled="f.processing">Krijo token</button></form></section><section class="tp-panel"><h2>Tokenet ekzistuese</h2><div v-if="tokens.length" class="tp-table-wrap"><table><thead><tr><th>Emri</th><th>Përdoruesi</th><th>Prefiksi</th><th>Lejet</th><th>Skadon</th><th>Përdorur</th><th>Gjendja</th><th></th></tr></thead><tbody><tr v-for="token in tokens" :key="token.id"><td>{{token.name}}</td><td>{{token.user_name}}</td><td><code>{{token.token_prefix}}…</code></td><td>{{JSON.parse(token.abilities).join(', ')}}</td><td>{{token.expires_at??'Pa skadim'}}</td><td>{{token.last_used_at??'—'}}</td><td>{{token.revoked_at?'I revokuar':'Aktiv'}}</td><td><button v-if="!token.revoked_at" class="tp-text-btn danger" @click="revoke(token.id)">Revoko</button></td></tr></tbody></table></div><p v-else class="tp-muted">Nuk ka tokena të krijuar.</p></section></template>
